// 只读字模BRAM：8192×8，9bit字符单元×16行；同步读延迟一个pixel拍。
// ASCII占1个8×16单元，192个汉字占左右2单元；码128..511已用满。
// address={glyph[8:0],row[3:0]}，row_bits[7]为最左像素；父层负责复位后的数据有效期。
// ui_font.hex相对工程根目录加载；运行脚本会设置正确cwd并拷贝ROM到隔离仿真目录。
// 资产映射在assets/ui_font_map.json；本版本不重新生成字体，也不扩容BRAM。
// 修改新中文必须先验证现有字库包含，否则generate_ui_text.py会拒绝生成。

// Generated by generate_font.py. Run/synthesize from the project root.
// address = {glyph[8:0], row[3:0]}; row_bits[7] is the leftmost pixel.
// One synchronous read stage; no reset or output initialization.
module hdmi_ui_font (
    input wire clk,
    input wire [12:0] address,
    output reg [7:0] row_bits
);
    reg [7:0] mem [0:8191] /* synthesis syn_romstyle = "block_rom" */;

    initial $readmemh("src/ui_font.hex", mem);

    always @(posedge clk)
        row_bits <= mem[address];
endmodule
